#include "Epidemic/GameFramework/Ownership/ownership.h"
using namespace epidemic::gameplay;using namespace epidemic::gameplay::ownership;
static GameplayObjectRef Ref(const char* n){return {GameplayDomainId::FromString("test"),GameplayObjectId::FromString(n)};}
int main(){OwnershipService o;auto player=Ref("player");auto npc=Ref("npc");auto item=Ref("item");auto take=PropertyRightId::FromString("right.take");OwnershipRecord r;r.property=item;r.owner=npc;r.strength=OwnershipStrength::Owned;auto rid=o.AssignOwnership(r);if(!rid)return 1;auto q=o.EvaluatePermission({player,item,take,{}});if(q.decision!=PermissionDecision::CrimeCandidate)return 2;PermissionGrant g;g.subject=player;g.property=item;g.right=take;auto gid=o.GrantPermission(g);if(!gid)return 3;q=o.EvaluatePermission({player,item,take,{}});if(q.decision!=PermissionDecision::Allowed)return 4;AccessRule ar;ar.property=item;ar.right=take;ar.decision=AccessDecision::Deny;ar.priority=100;auto arid=o.AddAccessRule(ar);if(!arid)return 5;q=o.EvaluatePermission({player,item,take,{}});if(q.decision!=PermissionDecision::Denied)return 6;if(!o.TransferOwnership({item,npc,player,TransferReason::Trade,{}}))return 7;if(!o.GetOwner(item)||o.GetOwner(item)->owner!=player)return 8;PropertyClaim c;c.property=item;c.claimant=npc;c.strength_micro=100;auto cid=o.CreateClaim(c);if(!cid)return 9;if(o.FindClaims(item).size()!=1)return 10;if(!o.ResolveClaim(cid.Value()))return 11;if(!o.FindClaims(item).empty())return 12;auto snap=o.CaptureSnapshot();OwnershipService restored;if(!restored.RestoreSnapshot(std::move(snap)))return 13;if(!restored.GetOwner(item)||restored.GetOwner(item)->owner!=player)return 14;if(restored.FindPropertiesOwnedBy(player).size()!=1)return 15;return 0;}
